CREATE TABLE inventory(id BIGSERIAL PRIMARY KEY,product_id BIGINT UNIQUE NOT NULL REFERENCES products(id),physical_stock NUMERIC(12,3) NOT NULL DEFAULT 0 CHECK(physical_stock>=0),reserved_stock NUMERIC(12,3) NOT NULL DEFAULT 0 CHECK(reserved_stock>=0 AND reserved_stock<=physical_stock),reorder_level NUMERIC(12,3) NOT NULL DEFAULT 10,version BIGINT NOT NULL DEFAULT 0); CREATE TABLE inventory_transactions(id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products(id),quantity_delta NUMERIC(12,3) NOT NULL,reason VARCHAR(80),created_at TIMESTAMPTZ DEFAULT now());